Method.Source:
protected void new()
{
    MwmsLogicBlockCreateQuarantineOrder qBlock = MwmsLogicBlockCreateQuarantineOrder::Construct();
    TFMLogicBlockTakeImage              imgBlock = new TFMLogicBlockTakeImage();      
    TFMLogicComponentDataContext        dataCon = imgBlock.components().getComponent(classStr(TFMLogicComponentDataContext));
    dataCon.parmInputData(tableStr(InventQuarantineOrder));
    dataCon.parmBlockName(classStr(MwmsLogicBlockCreateQuarantineOrder));
    processName = TFMConstants::CreateQuarantineOrders();
    super();
    this.addBlock(qBlock);
    //mBlock.parmInheritAndSuppress(true);

    this.addBlock(imgBlock);
    this.linkBlocks(qBlock,imgBlock,'1','1');
    //Activate Origin inheritance of values from InventDim

}

public static MwmsProcessCreateQuarantineOrder Construct()
{
    return new MwmsProcessCreateQuarantineOrder();
}
